using ProMaxx2.QA.Application.Common;using ProMaxx2.QA.Application.Projects;using ProMaxx2.QA.Application.TestManagement;using ProMaxx2.QA.Domain.Execution;
namespace ProMaxx2.QA.Application.Execution;
public sealed record EnvironmentDto(Guid TestEnvironmentId,Guid ProjectId,string EnvironmentName,string?BaseUrl,bool IsActive);public sealed record SaveEnvironmentRequest(Guid ProjectId,string EnvironmentName,string?BaseUrl,bool IsActive=true);public sealed record TestCycleDto(Guid TestCycleId,Guid ProjectId,Guid ReleaseId,string ReleaseCode,Guid BuildId,string BuildNumber,Guid EnvironmentId,string EnvironmentName,Guid?TestSuiteId,string?SuiteName,string CycleCode,string CycleName,string?CycleType,DateTime?StartDate,DateTime?EndDate,Guid?OwnerUserId,string Status,string?Notes,int CaseCount,int ExecutedCount,decimal ProgressPercent,IReadOnlyList<SuiteModuleDto> Modules,Guid?CreatedBy,string?CreatedByName,DateTime?CreatedAt);public sealed record SaveTestCycleRequest(Guid ProjectId,Guid ReleaseId,Guid BuildId,Guid EnvironmentId,Guid?TestSuiteId,string CycleCode,string CycleName,string?CycleType,DateTime?StartDate,DateTime?EndDate,Guid?OwnerUserId,string?Notes,bool PopulateFromSuite=true,bool RequiredOnly=false);public sealed record ChangeCycleStatusRequest(string Status);
public sealed record TestCycleOptionDto(Guid TestCycleId,Guid ProjectId,Guid ReleaseId,Guid BuildId,string CycleCode,string CycleName,string Status);
public sealed record TestCycleSummaryDto(int Total,int InProgress,int Completed,int Cancelled,int ExecutedCases,int TotalCases);
public sealed record TestCycleListResultDto(PagedResult<TestCycleDto> Items,TestCycleSummaryDto Summary);
public interface ITestCycleRepository{Task<IReadOnlyList<EnvironmentDto>>EnvironmentsAsync(Guid?projectId,CancellationToken ct);Task AddEnvironmentAsync(TestEnvironment entity,CancellationToken ct);Task<TestCycleListResultDto> ListAsync(Guid?projectId,Guid?releaseId,Guid?buildId,Guid?moduleId,string?search,string?status,string?cycleType,Guid?createdBy,int page,int size,CancellationToken ct);Task<IReadOnlyList<TestCycleOptionDto>> ListOptionsAsync(Guid?projectId,CancellationToken ct);Task<TestCycleDto?>GetAsync(Guid id,CancellationToken ct);Task<TestCycle?>FindAsync(Guid id,CancellationToken ct);Task<bool>CodeExistsAsync(Guid projectId,string code,Guid?excludeId,CancellationToken ct);Task<IReadOnlyList<string>>ListCodesAsync(Guid projectId,string prefix,CancellationToken ct);Task ValidateReferencesAsync(SaveTestCycleRequest r,CancellationToken ct);Task AddAsync(TestCycle entity,CancellationToken ct);Task PopulateAsync(Guid cycleId,Guid suiteId,bool requiredOnly,CancellationToken ct);Task DeleteAsync(TestCycle entity,CancellationToken ct);Task SaveAsync(CancellationToken ct);}
public sealed class TestCycleService(ITestCycleRepository repository,IProjectRepository projects){public Task<IReadOnlyList<EnvironmentDto>>EnvironmentsAsync(Guid?p,CancellationToken ct)=>repository.EnvironmentsAsync(p,ct);public async Task<EnvironmentDto>CreateEnvironmentAsync(SaveEnvironmentRequest r,CancellationToken ct){var e=new TestEnvironment(r.ProjectId,r.EnvironmentName,r.BaseUrl);await repository.AddEnvironmentAsync(e,ct);await repository.SaveAsync(ct);return(await repository.EnvironmentsAsync(r.ProjectId,ct)).Single(x=>x.TestEnvironmentId==e.TestEnvironmentId);}public Task<TestCycleListResultDto> ListAsync(Guid?projectId,Guid?releaseId,Guid?buildId,Guid?moduleId,string?search,string?status,string?cycleType,Guid?createdBy,int page,int size,CancellationToken ct)=>repository.ListAsync(projectId,releaseId,buildId,moduleId,search,status,cycleType,createdBy,page,size,ct);public Task<IReadOnlyList<TestCycleOptionDto>> ListOptionsAsync(Guid?projectId,CancellationToken ct)=>repository.ListOptionsAsync(projectId,ct);public Task<TestCycleDto?> GetAsync(Guid id,CancellationToken ct)=>repository.GetAsync(id,ct);public async Task<TestCycleDto>CreateAsync(SaveTestCycleRequest r,Guid?userId,CancellationToken ct){var project=await projects.GetAsync(r.ProjectId,ct)??throw new EntityNotFoundException("Project not found.");var code=string.IsNullOrWhiteSpace(r.CycleCode)?BusinessCodeGenerator.NextAvailable($"{project.ProjectCode}-CYC",await repository.ListCodesAsync(r.ProjectId,$"{project.ProjectCode}-CYC",ct)):r.CycleCode.Trim().ToUpperInvariant();if(await repository.CodeExistsAsync(r.ProjectId,code,null,ct))throw new DuplicateCodeException("Cycle code already exists.");await repository.ValidateReferencesAsync(r,ct);var e=new TestCycle(r.ProjectId,r.ReleaseId,r.BuildId,r.EnvironmentId,r.TestSuiteId,code,r.CycleName,r.CycleType,r.StartDate,r.EndDate,r.OwnerUserId,r.Notes,userId);await repository.AddAsync(e,ct);await repository.SaveAsync(ct);if(r.PopulateFromSuite&&r.TestSuiteId.HasValue){await repository.PopulateAsync(e.TestCycleId,r.TestSuiteId.Value,r.RequiredOnly,ct);await repository.SaveAsync(ct);}return(await repository.GetAsync(e.TestCycleId,ct))!;}public async Task<TestCycleDto>UpdateAsync(Guid id,SaveTestCycleRequest r,CancellationToken ct){var e=await repository.FindAsync(id,ct)??throw new EntityNotFoundException("Test cycle not found.");if(!string.IsNullOrWhiteSpace(r.CycleCode)){var newCode=r.CycleCode.Trim().ToUpperInvariant();if(newCode!=e.CycleCode){if(await repository.CodeExistsAsync(e.ProjectId,newCode,id,ct))throw new DuplicateCodeException("Cycle code already exists.");e.UpdateCode(newCode);}}e.Update(r.CycleName,r.CycleType,r.StartDate,r.EndDate,r.OwnerUserId,r.Notes);await repository.SaveAsync(ct);return(await repository.GetAsync(id,ct))!;}public async Task<TestCycleDto>StatusAsync(Guid id,string status,CancellationToken ct){var e=await repository.FindAsync(id,ct)??throw new EntityNotFoundException("Test cycle not found.");e.ChangeStatus(status);await repository.SaveAsync(ct);return(await repository.GetAsync(id,ct))!;}public async Task DeleteAsync(Guid id,Guid? userId,CancellationToken ct){var e=await repository.FindAsync(id,ct)??throw new EntityNotFoundException("Test cycle not found.");e.SoftDelete(userId);await repository.DeleteAsync(e,ct);await repository.SaveAsync(ct);}}
